using System;
using System.IO;
using System.Reflection;
using ColossalFramework;
using ColossalFramework.IO;
using ColossalFramework.Math;
using ColossalFramework.Plugins;
using ColossalFramework.Packaging;
using ColossalFramework.UI;
using HarmonyLib;
using HundredTiles.Runtime;
using UnityEngine;
public static class NativeEntry {
 public static string Root;static bool started,runnerCreated;public static bool Failed;
 public static void Main(string[] args){Root=Environment.GetEnvironmentVariable("HUNDREDTILES_SEVEN_ROOT");if(string.IsNullOrEmpty(Root)||!File.Exists(Path.Combine(Root,"isolated-test.marker")))return;new Harmony("HT.Seven.Boot").Patch(typeof(Debug).GetMethod("Log",new[]{typeof(object)}),new HarmonyMethod(typeof(NativeEntry).GetMethod("First")));}
 public static void Log(string s){File.AppendAllText(Path.Combine(Root,"checks.log"),DateTime.UtcNow.ToString("o")+" "+s+Environment.NewLine);}
 public static void First(){if(started)return;try{var p=Application.platform;}catch(MissingMethodException){return;}started=true;try{Install();}catch(Exception e){Log("BOOT FAILURE "+e);Failed=true;Application.Quit();}}
 static void Install(){Application.runInBackground=true;Directory.CreateDirectory(Path.Combine(Root,"UserData"));File.WriteAllText(Path.Combine(Root,"UserData/HundredTiles.startup-profile.txt"),"city");var h=new Harmony("HT.Seven.Isolation");h.Patch(typeof(DataLocation).GetProperty("localApplicationData").GetGetMethod(),new HarmonyMethod(typeof(NativeEntry).GetMethod("Local")));h.Patch(typeof(DataLocation).GetProperty("migrateProductFrom").GetSetMethod(),new HarmonyMethod(typeof(NativeEntry).GetMethod("NoMigration")));h.Patch(typeof(PluginManager).GetMethod("LoadPlugins"),postfix:new HarmonyMethod(typeof(NativeEntry).GetMethod("Enable")));h.Patch(typeof(Starter).GetMethod("Awake",BindingFlags.NonPublic|BindingFlags.Instance),new HarmonyMethod(typeof(NativeEntry).GetMethod("Before")),new HarmonyMethod(typeof(NativeEntry).GetMethod("After")));h.Patch(typeof(Harmony).GetMethod("Patch"),new HarmonyMethod(typeof(NativeEntry).GetMethod("TracePatch")));Application.logMessageReceivedThreaded+=Observe;Log("Isolated data redirect installed.");}
 public static void TracePatch(MethodBase __0){Log("PATCH "+__0.DeclaringType.FullName+"."+__0.Name);}
 public static bool Local(ref string __result){__result=Path.Combine(Root,"UserData");return false;}public static bool NoMigration(){return false;}
 public static void Before(){PluginManager.noWorkshop=true;PackageManager.noWorkshop=true;}
 public static void Enable(){foreach(var p in Singleton<PluginManager>.instance.GetPluginsInfo()){bool enable=Path.GetFullPath(p.modPath).StartsWith(Path.GetFullPath(Path.Combine(Root,"UserData/Addons/Mods"))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);p.isEnabled=enable;Log((enable?"Enabled ":"Disabled ")+Path.GetFileName(p.modPath));}}
 public static void After(){if(runnerCreated)return;runnerCreated=true;Log("After Starter before GameObject");var o=new GameObject("Seven mod verification");UnityEngine.Object.DontDestroyOnLoad(o);Log("Before runner component");o.AddComponent<NativeRunner>();Log("After runner component");}
 static void Observe(string s,string trace,LogType type){if(type!=LogType.Exception&&!s.StartsWith("Simulation error:"))return;Log("FAILURE "+s+"\n"+trace);Failed=true;}
}
public sealed class NativeRunner:MonoBehaviour {
 volatile bool simulationDone;bool firstUpdate;int phase;float began;string SaveName="SevenOfficialModsVerification";bool Reload{get{return Environment.GetEnvironmentVariable("HUNDREDTILES_SEVEN_RELOAD")=="1";}}
 void Awake(){NativeEntry.Log("Runner Awake");began=Time.realtimeSinceStartup;}
 void Update(){try{if(!firstUpdate){firstUpdate=true;NativeEntry.Log("Runner first Update");}if(NativeEntry.Failed){phase=9;Application.Quit();return;}if(phase==9)return;if(Time.realtimeSinceStartup-began>480)throw new Exception("Native verification timeout phase "+phase);if(!Singleton<LoadingManager>.exists)return;var lm=Singleton<LoadingManager>.instance;if(phase==0){if(lm.m_currentlyLoading||UIView.GetAView()==null)return;if(!Installer.IsInstalled)throw new Exception("Runtime failed to install before city load.");foreach(var a in PackageManager.FilterAssets(Reload?UserAssetType.SaveGameMetaData:UserAssetType.MapMetaData)){if(Reload&&(a.name!=SaveName||Path.GetFullPath(a.package.packagePath)!=Path.GetFullPath(Path.Combine(NativeEntry.Root,"UserData/Saves/"+SaveName+".crp"))))continue;var meta=new SimulationMetaData{m_CityName=SaveName,m_gameInstanceIdentifier=Guid.NewGuid().ToString(),m_currentDateTime=DateTime.Now,m_startingDateTime=DateTime.Now,m_disableAchievements=SimulationMetaData.MetaBool.True,m_updateMode=Reload?SimulationManager.UpdateMode.LoadGame:SimulationManager.UpdateMode.NewGameFromMap};Package.Asset asset;if(Reload)asset=a.Instantiate<SaveGameMetaData>().assetRef;else{var map=a.Instantiate<MapMetaData>();meta.m_MapName=map.mapName;meta.m_environment=map.environment;asset=map.assetRef;}phase=1;lm.LoadLevel(asset,"Game","InGame",meta);NativeEntry.Log("Requested isolated "+(Reload?"reload":"new map"));break;}return;}if(lm.m_currentlyLoading||!lm.m_simulationDataLoaded||!lm.m_loadingComplete)return;if(phase==1){NativeEntry.Log("City loaded; grid="+Singleton<GameAreaManager>.instance.m_areaGrid.Length+" tree capacity="+Singleton<TreeManager>.instance.m_trees.m_buffer.Length);if(Reload){if(File.Exists(Path.Combine(NativeEntry.Root,"far-ids.txt")))Geometry(false);NativeEntry.Log("PASS separate process native reload");if(Environment.GetEnvironmentVariable("HUNDREDTILES_SEVEN_RESAVE")=="1"){phase=2;Singleton<SimulationManager>.instance.AddAction(delegate{try{Geometry(true);simulationDone=true;}catch(Exception e){NativeEntry.Log("FAILURE "+e);NativeEntry.Failed=true;}});return;}phase=9;Application.Quit();return;}Singleton<SimulationManager>.instance.AddAction(delegate{try{NativeEntry.Log("Purchased tiles="+BulkUnlock.UnlockAll());Geometry(true);simulationDone=true;}catch(Exception e){NativeEntry.Log("FAILURE "+e);NativeEntry.Failed=true;}});phase=2;return;}if(phase==2){if(!simulationDone)return;var panel=UIView.library.Get<SavePanel>("SavePanel");if(panel==null)panel=UIView.library.Show<SavePanel>("SavePanel");if(panel==null||!panel.SaveGame(SaveName))return;phase=3;NativeEntry.Log("Requested native save");return;}if(phase==3&&!SavePanel.isSaving&&File.Exists(Path.Combine(NativeEntry.Root,"UserData/Saves/"+SaveName+".crp"))){NativeEntry.Log("PASS native save completed");phase=9;Application.Quit();}}catch(Exception e){phase=9;NativeEntry.Log("FAILURE "+e);Application.Quit();}}
 static void Geometry(bool create){var trees=Singleton<TreeManager>.instance;var props=Singleton<PropManager>.instance;float edge=-8640f+(float)Math.Sqrt(Singleton<GameAreaManager>.instance.m_areaGrid.Length)*1920f-400f;string record=Path.Combine(NativeEntry.Root,"far-ids.txt");float height=80;if(create)height=Singleton<TerrainManager>.instance.SampleDetailHeight(new Vector3(edge,0,edge))+20;else if(File.ReadAllLines(record).Length>2)height=float.Parse(File.ReadAllLines(record)[2],System.Globalization.CultureInfo.InvariantCulture);var p=new Vector3(edge,height,edge);uint tree;ushort prop;if(create){var random=new Randomizer(271);if(!trees.CreateTree(out tree,ref random,PrefabCollection<TreeInfo>.GetLoaded(0),p,true))throw new Exception("Far tree create failed");if(trees.m_trees.m_buffer.Length>262144){for(int i=0;tree<262144 && i<4096;i++)if(!trees.CreateTree(out tree,ref random,PrefabCollection<TreeInfo>.GetLoaded(0),p,true))throw new Exception("Expanded tree create failed");if(tree<262144)throw new Exception("No expanded tree slot exercised");}trees.m_trees.m_buffer[tree].FixedHeight=true;if(!props.CreateProp(out prop,ref random,PrefabCollection<PropInfo>.GetLoaded(0),p,0,true))throw new Exception("Far prop create failed");props.m_props.m_buffer[prop].Position=new Vector3(10.1234f,80,20.5678f);if((props.m_props.m_buffer[prop].Position-new Vector3(10.1234f,80,20.5678f)).sqrMagnitude>0.00001f)throw new Exception("Prop Control precision lost returning inside native map");props.m_props.m_buffer[prop].Position=p;File.WriteAllText(record,tree+"\n"+prop+"\n"+p.y.ToString(System.Globalization.CultureInfo.InvariantCulture));}else{var ids=File.ReadAllLines(record);tree=uint.Parse(ids[0]);prop=ushort.Parse(ids[1]);}Vector3 expectedTree=p;if(!create){float ground=Singleton<TerrainManager>.instance.SampleDetailHeight(p);expectedTree.y=trees.m_trees.m_buffer[tree].FixedHeight?Math.Max(p.y,ground):ground;}if((trees.m_trees.m_buffer[tree].Position-expectedTree).sqrMagnitude>1 || (props.m_props.m_buffer[prop].Position-p).sqrMagnitude>1)throw new Exception("Far packed position mismatch; tree="+trees.m_trees.m_buffer[tree].Position+" flags="+trees.m_trees.m_buffer[tree].m_flags+" prop="+props.m_props.m_buffer[prop].Position+" flags="+props.m_props.m_buffer[prop].m_flags+" expected="+p);NativeEntry.Log("PASS far tree/prop coordinates: "+edge+" create="+create);}
}
